let value = 0
basic.forever(function () {
    value = pins.analogReadPin(AnalogPin.P0)
    if (value >= 512) {
        pins.digitalWritePin(DigitalPin.P1, 1)
    } else {
        pins.digitalWritePin(DigitalPin.P1, 0)
    }
    pins.analogWritePin(AnalogPin.P2, value)
    basic.pause(20)
})
